"""CCDV-F group 2: Prompt and Context Engineering, Security and Safety, and Tools and MCPs.

Written against the Claude Certified Developer - Foundations exam guide (version 1.0, effective July 2026; domains 6, 7
and 8) and verified in October 2026 against the current Claude API, Claude Code, Agent SDK and Model Context Protocol
documentation. This group adds the Security and Safety flashcards, the questions for all three categories, their three
lessons, the games, one case study and the cheat sheet sections. IDs: cards f1301.., questions q1201.. / msq1201.. /
tf1201.., madlibs ml-ccdv-201.., sequences seq-ccdv-201.., compare cmp-ccdv-201..
"""


def _fc(i, cat, front, back, detail):
    return {'id': i, 'cat': cat, 'front': front, 'back': back, 'detail': detail}


def _mc(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'mc', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _ms(i, cat, question, options, correct, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'ms', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def _tf(i, cat, question, answer, explanation, why=None):
    q = {'id': i, 'cat': cat, 'type': 'tf', 'question': question, 'answer': answer, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


